<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-equals text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Chemistry Equation Balancer</h5><p class="text-muted small mb-0">Balance chemical reactions with step-by-step breakdown</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-12"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Chemical Equation</label><input type="text" id="in-eq" class="form-control form-control-lg" value="Fe + O2 = Fe2O3" placeholder="e.g. Fe + O2 = Fe2O3"></div><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="in-step" checked><label class="form-check-label small fw-bold text-secondary" for="in-step">Show Steps</label></div></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Law of Conservation of Mass:</b> atoms must be equal on both sides</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){function parse(c){var e={},re=/([A-Z][a-z]?)(\d*)/g,m;while((m=re.exec(c))!==null)if(m[1])e[m[1]]=(e[m[1]]||0)+parseInt(m[2]||"1");return e;}function balance(eq){eq=eq.replace(/→/g,"=").replace(/->/g,"=");var s=eq.split("=");if(s.length!==2)return null;var R=s[0].split("+").map(function(x){return x.trim();}).filter(Boolean);var P=s[1].split("+").map(function(x){return x.trim();}).filter(Boolean);var all=R.concat(P),n=all.length,parsed=all.map(parse);var els=new Set();parsed.forEach(function(p){for(var e in p)els.add(e);});els=[...els];function tryB(max){function chk(c){for(var ei=0;ei<els.length;ei++){var el=els[ei],l=0,r=0;for(var i=0;i<R.length;i++)l+=c[i]*(parsed[i][el]||0);for(var i=0;i<P.length;i++)r+=c[R.length+i]*(parsed[R.length+i][el]||0);if(l!==r)return false;}return true;}function en(idx,cur){if(idx===n)return chk(cur)?cur.slice():null;for(var c=1;c<=max;c++){cur[idx]=c;var r=en(idx+1,cur);if(r)return r;}return null;}return en(0,new Array(n).fill(1));}var co=tryB(n<=4?15:10);if(!co)return null;var rp=[],pp=[];for(var i=0;i<R.length;i++)rp.push((co[i]>1?co[i]:"")+R[i]);for(var i=0;i<P.length;i++)pp.push((co[R.length+i]>1?co[R.length+i]:"")+P[i]);return{balanced:rp.join(" + ")+" → "+pp.join(" + "),coeffs:co,R:R,P:P,els:els};}document.getElementById("btn-calc").addEventListener("click",function(){var eq=document.getElementById("in-eq").value.trim();if(!eq)return;var r=balance(eq);if(!r){document.getElementById("out-main").textContent="Could not balance";document.getElementById("out-unit").textContent="Check format";document.getElementById("out-ins").innerHTML="<p class=\"text-danger\">Use format: A + B = C + D</p>";}else{document.getElementById("out-main").textContent=r.balanced;document.getElementById("out-main").style.fontSize="1.5rem";document.getElementById("out-unit").textContent="Balanced";document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Reactants</div><div class="h5 fw-bold mb-0 text-primary">'+r.R.length+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Products</div><div class="h5 fw-bold mb-0 text-info">'+r.P.length+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Elements</div><div class="h5 fw-bold mb-0 text-success">'+r.els.length+'</div></div></div>';var ins=["Coefficients: ["+r.coeffs.join(", ")+"]","Atoms balanced on both sides ✓"];document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(x){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+"</li>";}).join("")+"</ul>";}document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-eq").value="Fe + O2 = Fe2O3";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>